_FASTMONAI_TRACKING_URI_SET = False  # did *we* set the tracking URI? (idempotency guard)


def _ensure_fastmonai_tracking_uri():
    """Point MLflow at fastMONAI's default sqlite store, once.

    Only sets the URI if the user has not configured MLflow themselves: if
    ``MLFLOW_TRACKING_URI`` is set or ``mlflow.set_tracking_uri`` was called
    (both reported by ``mlflow.is_tracking_uri_set()``), the user's choice is
    left untouched. Idempotent and safe to call repeatedly.
    """
    global _FASTMONAI_TRACKING_URI_SET
    if _FASTMONAI_TRACKING_URI_SET:
        return
    if mlflow.is_tracking_uri_set():
        _FASTMONAI_TRACKING_URI_SET = True  # respect the user's configuration
        return
    mlflow.set_tracking_uri(f"sqlite:///{_mlruns_db}")
    _FASTMONAI_TRACKING_URI_SET = True


def set_mlflow_tracking_uri(uri=None):
    """Point MLflow at a tracking store for fastMONAI runs (opt-in).

    Call once, before ``mlflow.set_experiment``/``mlflow.start_run`` or before
    creating fastMONAI's MLflow callbacks, to choose where runs are logged.

    Args:
        uri: A tracking URI (e.g. ``"sqlite:///runs.db"`` or an HTTP server).
            If ``None``, uses fastMONAI's default sqlite store at the
            package/repo root.

    Returns:
        The tracking URI that was set.
    """
    global _FASTMONAI_TRACKING_URI_SET
    if uri is None:
        uri = f"sqlite:///{_mlruns_db}"
    mlflow.set_tracking_uri(uri)
    _FASTMONAI_TRACKING_URI_SET = True
    return uri


def _resolve_backend_store_uri():
    """Backend store URI for the local ``mlflow ui`` server.

    Prefers a user-configured local store (sqlite/file/SQLAlchemy DB) so the UI
    shows the same runs fastMONAI logs to; falls back to fastMONAI's default
    sqlite store. An HTTP(S)/databricks tracking server cannot back a local UI,
    so it is not used here -- open that server's own UI instead. Read-only: never
    changes the global tracking URI (viewing must not reconfigure MLflow).
    """
    default = f"sqlite:///{_mlruns_db}"
    if not mlflow.is_tracking_uri_set():
        return default
    uri = mlflow.get_tracking_uri()
    if uri.startswith(("http://", "https://", "databricks")):
        return default
    return uri

