class ModelTrackingCallback(Callback):
    """
    A FastAI callback for comprehensive MLflow experiment tracking.
    
    This callback automatically logs hyperparameters, metrics, model artifacts,
    and configuration to MLflow during training. If a checkpoint callback
    (SaveModelCallback, EMACheckpoint, or any TrackerCallback with fname) is
    present, the best model checkpoint will also be logged as an artifact.
    
    Supports auto-managed runs when created via `create_mlflow_callback()`.
    """
    
    def __init__(
        self, 
        model_name: str, 
        loss_function: str, 
        item_tfms: list[Any],
        size: list[int], 
        target_spacing: list[float], 
        apply_reorder: bool,
        experiment_name: str = None,
        run_name: str = None,
        auto_start: bool = False,
        patch_config: dict = None,
        extra_params: dict = None,
        extra_tags: dict = None,
        dataset_version: str = None,
        log_split: bool = True
    ):
        """
        Initialize the MLflow tracking callback.
        
        Args:
            model_name: Name of the model architecture for registration
            loss_function: Name of the loss function being used
            item_tfms: List of item transforms
            size: Model input dimensions
            target_spacing: Resampling dimensions
            apply_reorder: Whether reordering augmentation is applied
            experiment_name: MLflow experiment name (used with auto_start)
            run_name: MLflow run name (auto-generated if None)
            auto_start: If True, auto-starts/stops MLflow run
            patch_config: Patch configuration dict for logging (from MedPatchDataLoaders)
            extra_params: Additional parameters to log
            extra_tags: MLflow tags to set on the run
            dataset_version: Dataset version hash string for tracking
            log_split: If True, auto-logs train/val split CSV when dls has split_df
        """
        _ensure_fastmonai_tracking_uri()
        self.model_name = model_name
        self.loss_function = loss_function
        self.item_tfms = item_tfms
        self.size = size
        self.target_spacing = target_spacing
        self.apply_reorder = apply_reorder
        
        self.experiment_name = experiment_name
        self.run_name = run_name
        self.auto_start = auto_start
        self.patch_config = patch_config
        self.extra_params = extra_params or {}
        self.extra_tags = extra_tags or {}
        self.dataset_version = dataset_version
        self.log_split = log_split
        self._auto_started = False
        self.run_id = None
        
        self.config = self._build_config()
        
    def extract_all_params(self, tfm):
        """
        Extract all parameters from a transform object for detailed logging.
        
        Args:
            tfm: Transform object to extract parameters from
            
        Returns:
            dict: Dictionary with 'name' and 'params' keys containing transform details
        """
        class_name = tfm.__class__.__name__
        params = {}
        
        for key, value in tfm.__dict__.items():
            if not key.startswith('_') and key != '__signature__':
                if hasattr(value, '__dict__') and hasattr(value, 'target_shape'):
                    params['target_shape'] = value.target_shape
                elif hasattr(value, '__dict__') and not key.startswith('_'):
                    nested_params = {k: v for k, v in value.__dict__.items() 
                                   if not k.startswith('_') and isinstance(v, (int, float, str, bool, tuple, list))}
                    params.update(nested_params)
                elif isinstance(value, (int, float, str, bool, tuple, list)):
                    params[key] = value
        
        return {
            'name': class_name,
            'params': params
        }
        
    def _build_config(self) -> dict[str, Any]:
        """Build configuration dictionary from initialization parameters."""
        transform_details = [self.extract_all_params(tfm) for tfm in self.item_tfms]
        
        return {
            "model_name": self.model_name,
            "loss_function": self.loss_function,
            "transform_details": transform_details,
            "size": self.size,
            "target_spacing": self.target_spacing,
            "apply_reorder": self.apply_reorder,
        }
    
    def _extract_training_params(self) -> dict[str, Any]:
        """Extract training hyperparameters from the learner."""
        params = {}
        
        params["epochs"] = self.learn.n_epoch
        params["learning_rate"] = float(self.learn.lr)
        params["optimizer"] = self.learn.opt_func.__name__
        params["batch_size"] = self.learn.dls.bs
        
        params["loss_function"] = self.config["loss_function"]
        params["size"] = self.config["size"]
        params["target_spacing"] = self.config["target_spacing"]
        params["apply_reorder"] = self.config["apply_reorder"]
        
        params["transformations"] = json.dumps(
            self.config["transform_details"], 
            indent=2, 
            separators=(',', ': ')
        )
        
        if self.patch_config:
            for key, value in self.patch_config.items():
                if value is not None:
                    params[f"patch_{key}"] = value if isinstance(value, (int, float, str, bool)) else str(value)
        
        return params
    
    def _extract_epoch_metrics(self) -> dict[str, float]:
        """Extract metrics from the current epoch."""
        recorder = self.learn.recorder
        
        # Skip 'epoch' and 'time'
        metric_names = recorder.metric_names[2:]
        raw_metric_values = recorder.log[2:]
        
        metrics = {}
        for name, val in zip(metric_names, raw_metric_values):
            if val is None:
                continue  # Skip None values during inference
            if isinstance(val, torch.Tensor):
                if val.numel() == 1:
                    metrics[name] = float(val)
                else:
                    val_list = val.tolist() if hasattr(val, 'tolist') else list(val)
                    for i, class_score in enumerate(val_list):
                        metrics[f"{name}_class_{i+1}"] = float(class_score)
                    metrics[f"{name}_mean"] = float(torch.mean(val))
            else:
                metrics[name] = float(val)
        
        if len(recorder.log) >= 2:
            if recorder.log[1] is not None:
                metrics['train_loss'] = float(recorder.log[1])
            if len(recorder.log) >= 3 and recorder.log[2] is not None:
                metrics['valid_loss'] = float(recorder.log[2])
                
        return metrics
    
    def _save_model_artifacts(self, temp_dir: Path) -> None:
        """Save model weights, learner, and configuration as artifacts."""
        import shutil

        # Save final epoch weights (without optimizer state to reduce file size)
        weights_path = temp_dir / "final_weights"
        self.learn.save(str(weights_path), with_opt=False)
        weights_file = f"{weights_path}.pth"
        if os.path.exists(weights_file):
            mlflow.log_artifact(weights_file, "model")

        # Auto-detect checkpoint callback (SaveModelCallback, EMACheckpoint, etc.)
        from fastai.callback.tracker import TrackerCallback
        best_model_cb = None
        for cb in self.learn.cbs:
            if isinstance(cb, TrackerCallback) and hasattr(cb, 'fname'):
                best_model_path = self.learn.path / self.learn.model_dir / f'{cb.fname}.pth'
                if best_model_path.exists():
                    best_weights_dest = temp_dir / "best_weights.pth"
                    shutil.copy2(str(best_model_path), str(best_weights_dest))
                    mlflow.log_artifact(str(best_weights_dest), "model")
                    print(f"Logged best model weights: best_weights.pth")
                    best_model_cb = cb
                break

        # Remove ModelTrackingCallback before exporting learners
        original_cbs = self.learn.cbs.copy()
        filtered_cbs = L([cb for cb in self.learn.cbs
                          if not isinstance(cb, ModelTrackingCallback)])
        self.learn.cbs = filtered_cbs

        # Export before loading best weights
        final_learner_path = temp_dir / "final_learner.pkl"
        self.learn.export(str(final_learner_path))
        mlflow.log_artifact(str(final_learner_path), "model")
        print("Logged final epoch learner: final_learner.pkl")

        if best_model_cb is not None:
            self.learn.load(best_model_cb.fname)
            print(f"Loaded best model weights ({best_model_cb.fname}) for best learner export")

            best_learner_path = temp_dir / "best_learner.pkl"
            self.learn.export(str(best_learner_path))
            mlflow.log_artifact(str(best_learner_path), "model")
            print("Logged best epoch learner: best_learner.pkl")

        self.learn.cbs = original_cbs

        config_path = temp_dir / "inference_settings.json"
        store_variables(config_path, self.size, self.apply_reorder, self.target_spacing)
        mlflow.log_artifact(str(config_path), "config")
    
    def _register_pytorch_model(self) -> None:
        """Register the PyTorch model with MLflow."""
        mlflow.pytorch.log_model(
            pytorch_model=self.learn.model,
            registered_model_name=self.model_name
        )

    def _log_split_df(self) -> None:
        """Log train/validation split as CSV artifact if available."""
        dls = self.learn.dls
        if not hasattr(dls, 'split_df'):
            return
        try:
            split_df = dls.split_df
            cols = []
            img_col = getattr(dls, '_img_col', None)
            mask_col = getattr(dls, '_mask_col', None)
            if img_col and img_col in split_df.columns:
                cols.append(img_col)
            if mask_col and mask_col in split_df.columns:
                cols.append(mask_col)
            cols.append('is_valid')
            split_df = split_df[cols]

            mlflow.log_text(split_df.to_csv(index=False), "data/train_val_split.csv")
            print(f"Logged train/val split ({len(split_df)} rows) to MLflow artifacts")
        except Exception as e:
            print(f"Warning: Could not log train/val split: {e}")

    def before_fit(self) -> None:
        """Log hyperparameters before training starts. Auto-start run if configured."""
        if self.auto_start:
            if self.experiment_name:
                mlflow.set_experiment(self.experiment_name)
            self.run_name = self.run_name or f"run_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
            mlflow.start_run(run_name=self.run_name)
            self._auto_started = True
        
        if self.dataset_version is not None:
            mlflow.set_tag("dataset_version", self.dataset_version)
        
        if self.extra_tags:
            mlflow.set_tags(self.extra_tags)
        
        params = self._extract_training_params()
        params.update(self.extra_params)
        mlflow.log_params(params)

        if self.log_split:
            self._log_split_df()
    
    def after_epoch(self) -> None:
        """Log metrics after each epoch."""
        metrics = self._extract_epoch_metrics()
        if metrics:
            mlflow.log_metrics(metrics, step=self.learn.epoch)
    
    def after_fit(self) -> None:
        """Log model artifacts after training completion."""
        print("\nTraining finished. Logging model artifacts to MLflow...")
        
        with tempfile.TemporaryDirectory() as temp_dir:
            temp_path = Path(temp_dir)
            
            self._save_model_artifacts(temp_path)
            
            self._register_pytorch_model()
        
        self.run_id = mlflow.active_run().info.run_id
        print(f"MLflow run completed. Run ID: {self.run_id}")
        
        if self._auto_started:
            mlflow.end_run()
            self._auto_started = False

    def log_metrics(self, metrics: dict) -> None:
        """Log additional metrics to the completed MLflow run.

        Reopens the run to log metrics, then closes it. Useful for
        post-training evaluation (e.g., validation set patch inference results).
        NaN values are silently skipped (MLflow rejects them).

        Args:
            metrics: Dictionary of metric name -> value pairs to log.
        """
        if self.run_id is None:
            raise RuntimeError("No MLflow run found. Train the model first.")

        import math
        valid = {k: v for k, v in metrics.items()
                 if not (isinstance(v, float) and math.isnan(v))}

        if valid:
            with mlflow.start_run(run_id=self.run_id):
                mlflow.log_metrics(valid)
            print(f"Logged {len(valid)} metric(s) to MLflow run {self.run_id}")

    def log_metrics_table(self, df, metrics=None, key='validation_metrics', display=False):
        """Log a summary table of metrics as an image to the MLflow Images tab.

        Creates a styled matplotlib table with Metric, Mean, and Std columns
        from the given DataFrame and logs it via mlflow.log_image() so it
        appears in the MLflow UI Images tab.

        Args:
            df: DataFrame containing per-sample metric values.
            metrics: List of column names in df to summarize. If None,
                all numeric columns are used automatically.
            key: Image key for MLflow Images tab.
            display: If True, display the table inline in the notebook.
        """
        import math
        import io
        import matplotlib.pyplot as plt
        from PIL import Image

        if self.run_id is None:
            raise RuntimeError("No MLflow run found. Train the model first.")

        if metrics is None:
            metrics = df.select_dtypes(include='number').columns.tolist()

        summary_data = []
        for metric in metrics:
            mean = df[metric].mean()
            std = df[metric].std()
            std_str = f'{std:.4f}' if not math.isnan(std) else 'N/A'
            summary_data.append([metric, f'{mean:.4f}', std_str])

        fig, ax = plt.subplots(figsize=(5, len(metrics) * 0.8 + 0.5))
        ax.axis('off')

        table = ax.table(
            cellText=summary_data,
            colLabels=['Metric', 'Mean', 'Std'],
            cellLoc='center',
            loc='center'
        )
        table.auto_set_font_size(False)
        table.set_fontsize(14)
        table.scale(1.5, 2.2)

        for col in range(3):
            table[0, col].set_facecolor('#4472C4')
            table[0, col].set_text_props(color='white', fontweight='bold')

        fig.tight_layout()

        buf = io.BytesIO()
        fig.savefig(buf, format='png', bbox_inches='tight', dpi=250)
        buf.seek(0)
        pil_image = Image.open(buf)

        with mlflow.start_run(run_id=self.run_id):
            mlflow.log_image(pil_image, key=key)

        buf.close()
        if display: plt.show()
        plt.close(fig)
        print(f"Logged metrics table to MLflow run {self.run_id}")

    def log_dataframe(self, df, artifact_name='validation_results.csv', artifact_path='results'):
        """Log a DataFrame as a CSV artifact to the MLflow run.

        Args:
            df: DataFrame to save.
            artifact_name: Filename for the CSV.
            artifact_path: Artifact subdirectory in MLflow.
        """
        if self.run_id is None:
            raise RuntimeError("No MLflow run found. Train the model first.")

        with tempfile.NamedTemporaryFile(suffix='.csv', delete=False, mode='w') as f:
            df.to_csv(f, index=False)
            temp_path = f.name

        with mlflow.start_run(run_id=self.run_id):
            mlflow.log_artifact(temp_path, artifact_path)

        os.remove(temp_path)
        print(f"Logged DataFrame ({len(df)} rows) to MLflow run {self.run_id}")

